UPDATE user
SET cnname = #{cnname},
    email = #{email},
    phone = #{phone},
    description = #{description}
WHERE user_name = #{userName}

mapper.select:
SELECT user_name AS userName, cnname, email, phone, description
FROM user
WHERE user_name = #{userName}
